  $hook = 'test';
  if ($this->moduleHandler()->hasImplementations('preprocess', [$prefix], TRUE)) {
    $function = "{$prefix}_preprocess";
    $preprocess_function[] = $function;
    $preprocess_invoke[$function] = ['module' => $prefix, 'hook' => 'preprocess'];
